#include <iostream>

#include <queue>

using namespace std;

void heapSort(int arr[], int n) {

    priority_queue<int> maxHeap;  // Max heap by default



    // Insert all elements

    for (int i = 0; i < n; i++) {

        maxHeap.push(arr[i]);

    }



    // Extract max elements in descending order

    for (int i = n - 1; i >= 0; i--) {

        arr[i] = maxHeap.top();

        maxHeap.pop();

    }

}

