class MaxHeap {

    constructor() {

        this.heap = [];

    }



    push(val) {

        this.heap.push(val);

        this.bubbleUp(this.heap.length - 1);

    }



    pop() {

        if (this.heap.length === 0) return null;

        const max = this.heap[0];

        this.heap[0] = this.heap[this.heap.length - 1];

        this.heap.pop();

        this.bubbleDown(0);

        return max;

    }



    bubbleUp(idx) {

        while (idx > 0) {

            const parentIdx = Math.floor((idx - 1) / 2);

            if (this.heap[idx] > this.heap[parentIdx]) {

                [this.heap[idx], this.heap[parentIdx]] = 

                    [this.heap[parentIdx], this.heap[idx]];

                idx = parentIdx;

            } else break;

        }

    }



    bubbleDown(idx) {

        const n = this.heap.length;

        while (2 * idx + 1 < n) {

            let largestIdx = idx;

            const left = 2 * idx + 1;

            const right = 2 * idx + 2;

            if (this.heap[left] > this.heap[largestIdx])

                largestIdx = left;

            if (right < n && this.heap[right] > this.heap[largestIdx])

                largestIdx = right;

            if (largestIdx !== idx) {

                [this.heap[idx], this.heap[largestIdx]] = 

                    [this.heap[largestIdx], this.heap[idx]];

                idx = largestIdx;

            } else break;

        }

    }

}

function heapSort(arr) {

    const maxHeap = new MaxHeap();

    arr.forEach(num => maxHeap.push(num));

    for (let i = arr.length - 1; i >= 0; i--) {

        arr[i] = maxHeap.pop();

    }

    return arr;

}

